4f0ab1c0a05f3dcb16a6aa090b7ec4fb2828ccf3145470d2\", \".evidence/qyh-selected-installation-preparation-scheduler-20261013/material-7.txt\": \"366366584b2854924e02beb50192107b8dc417264f4905000210ed74ef578e78\"}}, \"materials\": {\".evidence/qyh-selected-installation-preparation-scheduler-20261013/material-0.txt\": \"# 指定安装的原准备Scheduler入口\\nRules：用户既有恢复/安装授权、231原Lease/CAS/幂等/签名/租户合同，唯一m1，先方案/登记后RED与最小代码。方案先登记在parent current-api-candidate-and-installation-next-plan-20261013.md；本Task仅原live_installation_scheduler.py、新test_selected_live_installation_scheduler.py和本目录。\\n真实隔离原runtime-apply成功但只factory生成的owner不进入原scheduler.find_owner；全scope会读旧407成功未ACK outbox。新增run_selected_once(UUID)，只从原native bounded目录中构造/登记selected原Owner；既有owner延续原verify行为。共享原tick互斥/async shield/closing/stop语义，默认run_once仍原全scope。禁止捏造descriptor/手工map/假verify admission/旧Run/Source/Provider/current库写。\\n9条真实缺入口RED→53专项/首组相邻GREEN，新增Owner实际进入原RuntimeHost.has_current_preparation_assignment verify门的测试通过，117条原8文件累计GREEN（纯单元、不冒充PG验收）。扩大时旧uninstall断言漏lock，在25b8冻结代码实际同失败；独立Task校正only该测试具名lock并exact身份assert，原卸载不改。模型独立review当前格式/超时局部未完，不宣称PASS或Task最终完成。当前修改m1精确提交以供原Git冻结器纳入真实副本验收；保持Task active直到新冻结下原reset/apply/verify连续演练/独立复审与Delivery。\\n\", \".evidence/qyh-selected-installation-preparation-scheduler-20261013/material-1.txt\": \"\\\"\\\"\\\"Bounded process ownership for live installation lifecycle workers.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom dataclasses import dataclass\\nfrom uuid import UUID\\n\\nfrom .live_installation_owner import (\\n    LiveInstallationLifecycleOwner,\\n    LiveInstallationTick,\\n)\\nfrom .owned_control_consumer import _settled\\nfrom .pending_preparation_directory import (\\n    LiveInstallationOwnerFactory,\\n    PendingPreparationDescriptor,\\n    PostgresPendingPreparationDirectory,\\n)\\nfrom .preparation_owner import _observe\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass LiveInstallationSchedulerTick:\\n    deliveries: tuple[tuple[UUID, LiveInstallationTick], ...]\\n\\n\\nclass LiveInstallationScheduler:\\n    LIMIT = 100\\n\\n    def __init__(\\n        self,\\n        *,\\n        directory: PostgresPendingPreparationDirectory,\\n        factory: LiveInstallationOwnerFactory,\\n    ) -> None:\\n        if (\\n            type(directory) is not PostgresPendingPreparationDirectory\\n            or type(factory) is not LiveInstallationOwnerFactory\\n            or directory.scope != factory.scope\\n        ):\\n            raise TypeError(\\\"exact same-scope live installation scheduler inputs required\\\")\\n        self.directory = directory\\n        self.factory = factory\\n        self._owners: dict[UUID, LiveInstallationLifecycleOwner] = {}\\n        self._current_tick: asyncio.Task[LiveInstallationSchedulerTick] | None = None\\n        self._close_task: asyncio.Task[None] | None = None\\n        self._closing = False\\n        self._revoking = False\\n\\n    @property\\n    def owners(self) -> tuple[tuple[UUID, LiveInstallationLifecycleOwner], ...]:\\n        return tuple(sorted(self._owners.items()))\\n\\n    def find_owner(self, installation_id: UUID) -> LiveInstallationLifecycleOwner | None:\\n        if type(installation_id) is not UUID:\\n            raise TypeError(\\\"exact installation identity required\\\")\\n        return self._owners.get(installation_id)\\n\\n    async def _run(self, selected_installation: UUID | None = None) -> LiveInstallationSchedulerTick:\\n        descriptors = await _settled(\\n            asyncio.to_thread(self.directory.read_descriptors)\\n        )\\n        if (\\n            type(descriptors) is not tuple\\n            or len(descriptors) > self.LIMIT\\n            or any(type(item) is not PendingPreparationDescriptor for item in descriptors)\\n        ):\\n            raise TypeError(\\\"bounded pending preparation descriptors required\\\")\\n        if selected_installation is not None:\\n            installations = tuple(item.installation_id for item in descriptors)\\n            if (len(installations) != len(set(installations))\\n                    or any(item.scope != self.directory.scope for item in descriptors)):\\n                raise ValueError(\\\"selected preparation descriptors must be unique and same-scope\\\")\\n            descriptors = tuple(item for item in descriptors\\n                                if item.installation_id == selected_installation)\\n        for descriptor in descriptors:\\n            installation = descriptor.installation_id\\n            if installation not in self._owners:\\n                if len(self._owners) >= self.LIMIT:\\n                    raise RuntimeError(\\\"live installation owner limit exceeded\\\")\\n                owner = self.factory(descriptor)\\n                if type(owner) is not LiveInstallationLifecycleOwner:\\n                    raise TypeError(\\\"live installation factory returned invalid owner\\\")\\n                self._owners[installation] = owner\\n\\n        deliveries = []\\n        for installation, owner in self.owners:\\n            if selected_installation is not None and installation != selected_installation:\\n                continue\\n            result = await _settled(owner.run_once())\\n            if type(result) is not LiveInstallationTick:\\n                raise TypeError(\\\"live installation owner returned invalid tick\\\")\\n            deliveries.append((installation, result))\\n        return LiveInstallationSchedulerTick(tuple(deliveries))\\n\\n    async def run_once(self) -> LiveInstallationSchedulerTick:\\n        return await self._start_tick()\\n\\n    async def run_selected_once(self, installation_id: UUID) -> LiveInstallationSchedulerTick:\\n        \\\"\\\"\\\"Retain and advance only a native-directory-selected installation owner.\\\"\\\"\\\"\\n        if type(installation_id) is not UUID:\\n            raise TypeError(\\\"exact installation UUID required\\\")\\n        return await self._start_tick(installation_id)\\n\\n    async def _start_tick(self, selected_installation: UUID | None = None) -> LiveInstallationSchedulerTick:\\n        if self._closing or self._revoking:\\n            raise RuntimeError(\\\"live installation scheduler is closing\\\")\\n        if self._current_tick is not None and not self._current_tick.done():\\n            raise RuntimeError(\\\"live installation scheduler tick already in progress\\\")\\n        self._current_tick = asyncio.create_task(self._run(selected_installation))\\n        self._current_tick.add_done_callback(_observe)\\n        return await asyncio.shield(self._current_tick)\\n\\n    async def wait_idle(self) -> LiveInstallationSchedulerTick | None:\\n        if self._current_tick is None:\\n            return None\\n        return await asyncio.shield(self._current_tick)\\n\\n    async def revoke(\\n        self, installation_id: UUID, expected_owner: LiveInstallationLifecycleOwner\\n    ) -> None:\\n        if self._closing or self._revoking:\\n            raise RuntimeError(\\\"live installation scheduler is closing\\\")\\n        if type(installation_id) is not UUID or type(expected_owner) is not LiveInstallationLifecycleOwner:\\n            raise TypeError(\\\"exact live installation revocation required\\\")\\n        self._revoking = True\\n        try:\\n            await _settled(self.wait_idle())\\n            current = self._owners.get(installation_id)\\n            if current is not expected_owner:\\n                raise LookupError(\\\"live installation owner identity changed\\\")\\n            del self._owners[installation_id]\\n            await _settled(current.stop())\\n        finally:\\n            self._revoking = False\\n\\n    async def _close(self) -> None:\\n        original: BaseException | None = None\\n        try:\\n            await _settled(self.wait_idle())\\n        except BaseException as exc:\\n            original = exc\\n        owners = tuple(owner for _, owner in self.owners)\\n        self._owners.clear()\\n        for owner in owners:\\n            try:\\n                await _settled(owner.stop())\\n            except BaseException as exc:\\n                if original is None:\\n                    original = exc\\n        if original is not None:\\n            raise original\\n\\n    async def stop(self) -> None:\\n        self._closing = True\\n        if self._close_task is None:\\n            self._close_task = asyncio.create_task(self._close())\\n            self._close_task.add_done_callback(_observe)\\n        await asyncio.shield(self._close_task)\\n\", \".evidence/qyh-selected-installation-preparation-scheduler-20261013/material-2.txt\": \"\\\"\\\"\\\"Selected preparation retains the original owner without dispatching unrelated work.\\\"\\\"\\\"\\nimport asyncio\\nfrom uuid import UUID\\nimport pytest\\nfrom test_live_installation_scheduler import dependencies,descriptor,SCOPE\\nfrom aos_api.extension_runtime.live_installation_scheduler import LiveInstallationScheduler\\nfrom aos_api.extension_runtime.pending_preparation_directory import PendingPreparationDescriptor\\nfrom aos_api.extension_runtime.runtime_host import RuntimeHost,RuntimeTenantAssignment\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\ndef test_selected_retains_only_native_selected_owner_for_followup(monkeypatch):\\n calls=[];directory,factory,owners=dependencies(monkeypatch,((descriptor(1),descriptor(2)),()),calls)\\n async def run():\\n  scheduler=LiveInstallationScheduler(directory=directory,factory=factory)\\n  assignment=RuntimeTenantAssignment(scope=SCOPE,lifecycle=scheduler)\\n  host=RuntimeHost(assignments=lambda:(assignment,))\\n  assert not host.has_current_preparation_assignment(SCOPE,kind='runtime-verify',installation_id=UUID(int=2))\\n  first=await scheduler.run_selected_once(UUID(int=2))\\n  assert [i.int for i,_ in first.deliveries]==[2]\\n  original=scheduler.find_owner(UUID(int=2));assert original is owners[UUID(int=2)]\\n  assert host.has_current_preparation_assignment(SCOPE,kind='runtime-verify',installation_id=UUID(int=2))\\n  assert not host.has_current_preparation_assignment(SCOPE,kind='runtime-verify',installation_id=UUID(int=1))\\n  second=await scheduler.run_selected_once(UUID(int=2))\\n  assert [i.int for i,_ in second.deliveries]==[2] and scheduler.find_owner(UUID(int=2)) is original\\n  assert scheduler.find_owner(UUID(int=1)) is None\\n  await scheduler.stop()\\n asyncio.run(run());assert calls==[('create',2),('run',2),('run',2),('stop',2)]\\n\\n\\ndef test_selected_does_not_dispatch_an_existing_unselected_owner(monkeypatch):\\n calls=[];directory,factory,_=dependencies(monkeypatch,((descriptor(1),descriptor(2)),()),calls)\\n async def run():\\n  scheduler=LiveInstallationScheduler(directory=directory,factory=factory)\\n  await scheduler.run_once();calls.clear()\\n  await scheduler.run_selected_once(UUID(int=2));assert calls==[('run',2)]\\n  await scheduler.stop()\\n asyncio.run(run());assert calls==[('run',2),('stop',1),('stop',2)]\\n\\n\\ndef test_missing_target_has_no_fabricated_descriptor_or_owner(monkeypatch):\\n calls=[];directory,factory,_=dependencies(monkeypatch,((descriptor(1),),),calls)\\n async def run():\\n  scheduler=LiveInstallationScheduler(directory=directory,factory=factory)\\n  result=await scheduler.run_selected_once(UUID(int=9));assert result.deliveries==() and scheduler.owners==()\\n  await scheduler.stop()\\n asyncio.run(run());assert calls==[]\\n\\n\\n@pytest.mark.parametrize('target',[None,'00000000-0000-0000-0000-000000000002',2])\\ndef test_selected_rejects_non_uuid_before_directory_read(monkeypatch,target):\\n calls=[];directory,factory,_=dependencies(monkeypatch,(),calls)\\n async def run():\\n  scheduler=LiveInstallationScheduler(directory=directory,factory=factory)\\n  with pytest.raises(TypeError,match='UUID'):await scheduler.run_selected_once(target)\\n  await scheduler.stop()\\n asyncio.run(run());assert calls==[]\\n\\n\\n@pytest.mark.parametrize('page',[(descriptor(2),descriptor(2)),(PendingPreparationDescriptor(TenantScope('dev-org','dev-project'),UUID(int=2)),)])\\ndef test_selected_rejects_duplicate_or_cross_scope_native_page(monkeypatch,page):\\n calls=[];directory,factory,_=dependencies(monkeypatch,(page,),calls)\\n async def run():\\n  scheduler=LiveInstallationScheduler(directory=directory,factory=factory)\\n  with pytest.raises((TypeError,ValueError)):await scheduler.run_selected_once(UUID(int=2))\\n  with pytest.raises((TypeError,ValueError)):await scheduler.stop()\\n asyncio.run(run());assert calls==[]\\n\\n\\ndef test_selected_and_legacy_share_one_tick_and_stop_awaits_owned_work(monkeypatch):\\n calls=[]\\n async def run():\\n  entered,release=asyncio.Event(),asyncio.Event()\\n  directory,factory,_=dependencies(monkeypatch,((descriptor(2),),),calls,block=(2,entered,release))\\n  scheduler=LiveInstallationScheduler(directory=directory,factory=factory)\\n  request=asyncio.create_task(scheduler.run_selected_once(UUID(int=2)));await entered.wait()\\n  with pytest.raises(RuntimeError,match='already in progress'):await scheduler.run_once()\\n  with pytest.raises(RuntimeError,match='already in progress'):await scheduler.run_selected_once(UUID(int=2))\\n  request.cancel()\\n  with pytest.raises(asyncio.CancelledError):await request\\n  closing=asyncio.create_task(scheduler.stop());await asyncio.sleep(0)\\n  assert not closing.done() and ('stop',2) not in calls\\n  release.set();await closing\\n  with pytest.raises(RuntimeError,match='closing'):await scheduler.run_selected_once(UUID(int=2))\\n asyncio.run(run());assert calls==[('create',2),('run',2),('stop',2)]\\n\", \".evidence/qyh-selected-installation-preparation-scheduler-20261013/material-3.txt\": \"from __future__ import annotations\\n\\nimport asyncio\\nfrom uuid import UUID\\n\\nimport pytest\\n\\nfrom aos_api.extension_runtime.live_installation_owner import (\\n    LiveInstallationLifecycleOwner,\\n    LiveInstallationTick,\\n)\\nfrom aos_api.extension_runtime.live_installation_scheduler import (\\n    LiveInstallationScheduler,\\n)\\nfrom aos_api.extension_runtime.pending_preparation_directory import (\\n    LiveInstallationOwnerFactory,\\n    PendingPreparationDescriptor,\\n    PostgresPendingPreparationDirectory,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nSCOPE = TenantScope(\\\"org-org\\\", \\\"dev-project\\\")\\n\\n\\ndef descriptor(value):\\n    return PendingPreparationDescriptor(SCOPE, UUID(int=value))\\n\\n\\ndef dependencies(monkeypatch, pages, calls, *, fail=None, block=None, stop_fail=()):\\n    directory = object.__new__(PostgresPendingPreparationDirectory)\\n    directory.scope = SCOPE\\n    pages = iter(pages)\\n    directory.read_descriptors = lambda: next(pages)\\n    factory = object.__new__(LiveInstallationOwnerFactory)\\n    factory.scope = SCOPE\\n    owners = {}\\n\\n    def create(_factory, item):\\n        calls.append((\\\"create\\\", item.installation_id.int))\\n        owner = object.__new__(LiveInstallationLifecycleOwner)\\n\\n        async def run_once():\\n            calls.append((\\\"run\\\", item.installation_id.int))\\n            if block is not None and item.installation_id.int == block[0]:\\n                block[1].set()\\n                await block[2].wait()\\n            if item.installation_id.int == fail:\\n                raise RuntimeError(\\\"named owner failure\\\")\\n            return LiveInstallationTick(None, None, None)\\n\\n        async def stop():\\n            calls.append((\\\"stop\\\", item.installation_id.int))\\n            if item.installation_id.int in stop_fail:\\n                raise RuntimeError(f\\\"stop {item.installation_id.int} failed\\\")\\n\\n        owner.run_once = run_once\\n        owner.stop = stop\\n        owners[item.installation_id] = owner\\n        return owner\\n\\n    monkeypatch.setattr(LiveInstallationOwnerFactory, \\\"__call__\\\", create)\\n    return directory, factory, owners\\n\\n\\ndef test_requires_exact_same_scope_dependencies():\\n    with pytest.raises(TypeError, match=\\\"same-scope\\\"):\\n        LiveInstallationScheduler(directory=object(), factory=object())\\n    directory = object.__new__(PostgresPendingPreparationDirectory)\\n    directory.scope = SCOPE\\n    factory = object.__new__(LiveInstallationOwnerFactory)\\n    factory.scope = TenantScope(\\\"other\\\", \\\"project\\\")\\n    with pytest.raises(TypeError, match=\\\"same-scope\\\"):\\n        LiveInstallationScheduler(directory=directory, factory=factory)\\n\\n\\ndef test_creates_in_uuid_order_and_retains_after_descriptor_disappears(monkeypatch):\\n    calls = []\\n    directory, factory, owners = dependencies(\\n        monkeypatch,\\n        ((descriptor(1), descriptor(2)), ()),\\n        calls,\\n    )\\n\\n    async def exercise():\\n        scheduler = LiveInstallationScheduler(directory=directory, factory=factory)\\n        first = await scheduler.run_once()\\n        second = await scheduler.run_once()\\n        assert tuple(key.int for key, _ in scheduler.owners) == (1, 2)\\n        assert len(first.deliveries) == len(second.deliveries) == 2\\n        await scheduler.stop()\\n\\n    asyncio.run(exercise())\\n    assert calls == [\\n        (\\\"create\\\", 1), (\\\"create\\\", 2), (\\\"run\\\", 1), (\\\"run\\\", 2),\\n        (\\\"run\\\", 1), (\\\"run\\\", 2), (\\\"stop\\\", 1), (\\\"stop\\\", 2),\\n    ]\\n    assert len(owners) == 2\\n\\n\\ndef test_owner_failure_stops_tick_before_later_owner_and_stop_cleans_all(monkeypatch):\\n    calls = []\\n    directory, factory, _ = dependencies(\\n        monkeypatch, ((descriptor(1), descriptor(2)),), calls, fail=1\\n    )\\n\\n    async def exercise():\\n        scheduler = LiveInstallationScheduler(directory=directory, factory=factory)\\n        with pytest.raises(RuntimeError, match=\\\"named owner failure\\\"):\\n            await scheduler.run_once()\\n        with pytest.raises(RuntimeError, match=\\\"named owner failure\\\"):\\n            await scheduler.s